// Builds the Automations tab's images (../automations/): a 16:9 thumbnail per automation that shows what it does, and
// each app's icon. ROB IT's own automations use the creative's real pictures where one shows the task (its thumbnails in
// ../../rbx/assets and ../../img/iter, frames of its captured Roblox pages), cropped and composed; every other one is
// generated by fal's nano-banana-pro from a prompt naming that task's output, with ROB IT's art as the reference where
// the output is of this game. A generated thumbnail already on disk is kept (pass ids, or "all", to make them again);
// each request's prompt and id goes to ../automations/prompts.03378ba4.json. Icons are each app's own, from its site.
// Provenance: ../automations/CREDITS.txt.
// node sidebars.bdeb2397/tools/automations-assets.03378ba4.mjs http://localhost:5297/ [all | id ...]
import { createRequire } from 'node:module';
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
const require = createRequire(import.meta.url);
const { chromium } = require('playwright');

const [BASE = 'http://localhost:5297/', ...REGEN] = process.argv.slice(2);
const ROOT = fileURLToPath(new URL('../../', import.meta.url));
const OUT = fileURLToPath(new URL('../automations/', import.meta.url));
const LOG = join(OUT, 'prompts.03378ba4.json');
const TMP = mkdtempSync(join(tmpdir(), 'automations-assets-'));
mkdirSync(join(OUT, 'apps'), { recursive: true });

const W = 768, H = 432; // the size of ROB IT's own thumbnails as Creator Hub serves them
const GROUND = '#f2f2f7', INK = '#1c1c1e'; // tokens.bdeb2397.css --ground, --ink
const WIN = '#34c759'; // the system green, on the winning thumbnail's check
const FONT = '/System/Library/Fonts/SFNSRounded.ttf';
const MODEL = 'fal-ai/nano-banana-pro', PRICE = 0.15; // USD per image, fal's pricing API, 2026-10-21
const CONCURRENCY = 6;
const src = (path) => join(ROOT, path);
const magick = (...args) => execFileSync('magick', args.flat(Infinity), { stdio: ['ignore', 'ignore', 'inherit'] });
const webp = ['-strip', '-quality', '82'];

// one picture filling 16:9, cut from its middle (or the side `gravity` names)
const fill = (from, to, gravity = 'center') => magick(from, '-resize', `${W}x${H}^`, '-gravity', gravity, '-extent', `${W}x${H}`, webp, to);

