function falKey() {
  const key = execFileSync('security', ['find-generic-password', '-s', 'fal-key', '-w'], { encoding: 'utf8' }).trim();
  if (!key) throw new Error('no fal key in the keychain (service fal-key)');
  return key;
}

// a reference picture as a data URI, re-encoded as JPEG
function dataUri(path) {
  const jpg = join(TMP, `ref-${path.replace(/\W/g, '_')}.jpg`);
  magick(src(path), '-quality', '90', jpg);
  return `data:image/jpeg;base64,${readFileSync(jpg).toString('base64')}`;
}

async function generate(id, { prompt, refs = [] }, key) {
  const endpoint = refs.length ? `${MODEL}/edit` : MODEL;
  const input = { prompt: `${prompt} ${STYLE}`, aspect_ratio: '16:9', resolution: '1K', output_format: 'png', num_images: 1, ...(refs.length && { image_urls: refs.map(dataUri) }) };
  const res = await fetch(`https://fal.run/${endpoint}`, { method: 'POST', headers: { Authorization: `Key ${key}`, 'Content-Type': 'application/json' }, body: JSON.stringify(input), signal: AbortSignal.timeout(300000) });
  if (!res.ok) throw new Error(`${id}: ${endpoint} answered ${res.status}: ${(await res.text()).slice(0, 400)}`);
  const json = await res.json();
  const url = json.images?.[0]?.url;
  if (!url) throw new Error(`${id}: ${endpoint} returned no image: ${JSON.stringify(json).slice(0, 400)}`);
  const img = await fetch(url);
  if (!img.ok) throw new Error(`${id}: the image at ${url} answered ${img.status}`);
  const raw = join(TMP, `${id}.png`);
  writeFileSync(raw, Buffer.from(await img.arrayBuffer()));
  fill(raw, join(OUT, `${id}.webp`));
  return { id, endpoint, prompt, refs, request_id: res.headers.get('x-fal-request-id') ?? json.request_id ?? null, at: new Date().toISOString() };
}

async function generateAll() {
  const want = Object.keys(PROMPTS).filter((id) => REGEN.includes('all') || REGEN.includes(id) || !existsSync(join(OUT, `${id}.webp`)));
  if (!want.length) return console.log('generated thumbnails: all on disk');
  const key = falKey();
  const log = existsSync(LOG) ? JSON.parse(readFileSync(LOG, 'utf8')) : {};
  const failed = [];
  for (let i = 0; i < want.length; i += CONCURRENCY) {
    const batch = want.slice(i, i + CONCURRENCY);
    const results = await Promise.allSettled(batch.map((id) => generate(id, PROMPTS[id], key)));
    results.forEach((r, j) => {
      if (r.status === 'fulfilled') { log[r.value.id] = r.value; console.log(`generated ${r.value.id}`); } else { console.error(r.reason); failed.push(batch[j]); }
    });
    writeFileSync(LOG, `${JSON.stringify(log, null, 1)}\n`);
  }
  const made = want.length - failed.length;
  console.log(`generated ${made} with ${MODEL} (about $${(made * PRICE).toFixed(2)})`);
  if (failed.length) throw new Error(`not generated: ${failed.join(', ')}`);
}

// ---------- ROB IT's own pictures, where one already shows the task ----------
async function captures() {
  const browser = await chromium.launch({ headless: true });
  try {
    // Creator Hub's Thumbnails page as the spot's live view shows it at 48s, without superbot's takeover edge, Stop
    // pill and cursor: its performance table, right of the page's own nav and below Chrome's toolbar
    const spot = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 2 });
    await spot.goto(`${BASE}sidebars.bdeb2397/view.03378ba4.html?v=1&t=48`);
    await spot.waitForFunction(() => window.__ready === true, null, { timeout: 30000 });
    await spot.addStyleTag({ content: '.cc-edge, .cc-stop, .cc-cursor { display: none !important; }' });
    const box = await spot.locator('.cc-view').boundingBox();
    if (!box || box.x + box.width > 1921) throw new Error(`the live view is not on screen at 48s: ${JSON.stringify(box)}`);
    const px = box.width / 1470; // one of the desktop's px, which is 1470 wide
    const hub = { x: box.x + 420 * px, y: box.y + 300 * px, width: 1040 * px, height: 1040 * px * 9 / 16 };
    await spot.screenshot({ path: join(TMP, 'hub.png'), clip: hub });
  } finally {
    await browser.close();
  }
}

// the thumbnail test itself: the gold vault thumbnail (A, 0.58% play-through in the spot's chat) beside iteration 1,
// which replaced it (B, 1.34%), B ringed and checked as the keeper
function abTest(to) {
  const w = 344, h = 194, gap = 24, x0 = (W - 2 * w - gap) / 2, y = (H - h) / 2, r = 12;
  const tiles = [['rbx/assets/a3def5f381990d.webp', 'A'], ['img/iter/iter-3.webp', 'B']].map(([from, label], i) => {
    const t = join(TMP, `ab-${i}.png`);
    magick(src(from), '-resize', `${w}x${h}^`, '-gravity', 'center', '-extent', `${w}x${h}`,
      '(', '-size', `${w}x${h}`, 'xc:none', '-fill', 'white', '-draw', `roundrectangle 0,0 ${w - 1},${h - 1} ${r},${r}`, ')',
      '-alpha', 'set', '-compose', 'DstIn', '-composite', '-compose', 'Over',
      '-fill', 'rgba(255,255,255,0.92)', '-draw', 'roundrectangle 10,10 42,38 8,8',
      '-font', FONT, '-pointsize', '18', '-fill', INK, '-gravity', 'northwest', '-annotate', '+19+13', label, t);
    return t;
  });
  const bx = x0 + w + gap;
  magick('-size', `${W}x${H}`, `xc:${GROUND}`,
    tiles[0], '-geometry', `+${x0}+${y}`, '-composite',
    '-fill', 'none', '-stroke', WIN, '-strokewidth', '5', '-draw', `roundrectangle ${bx - 4},${y - 4} ${bx + w + 3},${y + h + 3} ${r + 4},${r + 4}`,
    tiles[1], '-geometry', `+${bx}+${y}`, '-composite',
    '-stroke', 'none', '-fill', WIN, '-draw', `circle ${bx + w - 6},${y + 6} ${bx + w + 12},${y + 6}`,
    '-fill', 'none', '-stroke', 'white', '-strokewidth', '4', '-draw', `polyline ${bx + w - 14},${y + 6} ${bx + w - 8},${y + 12} ${bx + w + 3},${y}`,
    webp, to);
}

